  // S900 Datalink
  'digitalFpv.s900.name': 'S900 Integrated Digital Datalink',
  'digitalFpv.s900.slogan': 'Industrial Data & Telemetry Radio',
  'digitalFpv.s900.subSlogan': '12KM Range | 915MHz FHSS | Point-to-Multipoint | MAVLink Compatible',
  'digitalFpv.s900.description': 'The S900 is a professional integrated digital datalink providing bidirectional telemetry (MAVLink), RC control, and data transmission in one compact 21g unit. Utilizing industry-leading SDR technology, it achieves long-range stable communication at extremely low power (20dBm). Supports point-to-point, point-to-multipoint, and relay networking — the communication backbone for industrial UAV platforms.',
  'digitalFpv.s900.keyFeature.1': '12KM Range',
  'digitalFpv.s900.keyFeature.2': '902-928MHz FHSS',
  'digitalFpv.s900.keyFeature.3': 'Multi-Point Networking',
  'digitalFpv.s900.keyFeature.4': '2S-20S Wide Voltage',
  'digitalFpv.s900.feature.1.title': 'Ultra Long Range Communication',
  'digitalFpv.s900.feature.1.desc': 'Maximum range of 12KM (open environment, ground-to-air at 120m altitude). Stable bidirectional MAVLink telemetry for BVLOS missions.',
  'digitalFpv.s900.feature.2.title': 'Advanced SDR Technology',
  'digitalFpv.s900.feature.2.desc': 'Industry-leading Software Defined Radio enables long-range high-speed bidirectional communication at low transmit power, simplifying RF architecture.',
  'digitalFpv.s900.feature.3.title': 'FHSS Anti-Interference',
  'digitalFpv.s900.feature.3.desc': '915MHz FHSS automatic frequency hopping provides strong anti-interference capability for stable communication in complex electromagnetic environments.',
  'digitalFpv.s900.feature.4.title': 'Point-to-Multipoint Networking',
  'digitalFpv.s900.feature.4.desc': 'Supports point-to-point, point-to-multipoint, and relay networking modes — ideal for swarm coordination and multi-UAV fleet management.',
  'digitalFpv.s900.feature.5.title': 'Wide Voltage Input (2S-20S)',
  'digitalFpv.s900.feature.5.desc': 'Supports 2S-20S wide voltage input, compatible with platforms from small tactical drones to heavy-lift industrial UAVs.',
  'digitalFpv.s900.feature.6.title': 'MAVLink & FC Integration',
  'digitalFpv.s900.feature.6.desc': 'Plug-and-play with Pixhawk, CubePilot and ArduPilot flight controllers via GH1.25-4P interface. Full Mission Planner and QGroundControl compatibility.',
