  'about.seoTitle': 'About CANI Technology | Industrial UAV Core Payload & VTX System R&D Expert',
  'about.seoDescription': 'CANI Technology, a High-Tech Enterprise founded in 2015, specializes in industrial UAV core component R&D. Core products include 37W high-power VTX, 50km long-range datalinks, and IP67-rated EO/IR gimbal pods for power inspection and security missions.',
  'about.seoKeywords': 'CANI Technology,industrial UAV manufacturer,37W VTX R&D,UAV core board customization,high-tech drone enterprise',
  'about.bluf': 'CANI Technology, founded in 2015, is a High-Tech Enterprise specializing in UAV core technology R&D. Our core capabilities span 37W ultra-high-power digital video transmission (VTX), precision 3-axis stabilized gimbal pods, and industrial-grade flight control systems. CANI\'s solutions are deployed across BVLOS missions globally, delivering 50km-class HD datalinks for power inspection, security, and surveying industries.',
  'about.competencies.title': 'Full-Stack Core Moat: From Link to Flight',
  'about.competencies.subtitle': 'More than a module supplier — a full-stack system integrator owning both the code and the circuit. CANI delivers closed-loop "digital organisms" for clients.',
