  'vtx.notes.intro': 'As professional high-power analog video transmission accessories, please strictly follow the installation requirements during system setup to ensure proper device operation and maximum NLOS performance.',

  // FC/ESC Category Page
  'fcesc.seo.title': 'High-Performance UAV Flight Controllers & ESCs | H7 FC & FOC ESC Stacks | CANI Technology',
  'fcesc.seo.description': 'Explore industrial-grade flight controllers and ESCs for UAVs. Features STM32 H743/753 MCUs, triple redundancy IMUs, and high-voltage FOC ESCs (up to 24S). Supports DroneCAN, MAVLink, and Betaflight protocols for BVLOS missions.',
  'fcesc.hero.title': 'Industrial UAV Flight Controllers & ESC Power Systems',
  'fcesc.hero.desc': 'High-performance FC/ESC product line featuring STM32 H7 autopilots with triple-redundant IMUs, FOC ESCs up to 200A/24S, and plug-and-play stacks for professional FPV & cinematography. NDAA-compliant hardware available.',
  'fcesc.back': 'Back to Accessories',
  'fcesc.getQuote': 'Get a Quote',
  'fcesc.viewProducts': 'View Products',
  'fcesc.feature.cpu': 'H7 Series MCU',
  'fcesc.feature.cpu.desc': 'STM32H743/H753 at 480MHz with hardware FPU for complex Kalman filtering and real-time obstacle avoidance.',
  'fcesc.feature.current': 'High-Voltage FOC ESC',
  'fcesc.feature.current.desc': 'Smart FOC vector control, 80A-200A continuous, up to 24S (100V+), optimized for heavy-lift industrial UAVs.',
  'fcesc.feature.heat': 'Industrial Thermal Design',
  'fcesc.feature.heat.desc': 'Aluminum substrate with optimized heat paths ensures stable operation under sustained high-current loads.',
  'fcesc.feature.protection': 'Multi-Layer Protection',
  'fcesc.feature.protection.desc': 'Over-current, over-temperature, motor lock-up, and under-voltage protection for industrial-grade hardware safety.',
  'fcesc.feature.config': 'Multi-Protocol Support',
  'fcesc.feature.config.desc': 'Supports PX4, ArduPilot, Betaflight/iNav. DroneCAN, MAVLink, and UART interfaces for full ecosystem compatibility.',
  'fcesc.feature.plug': 'Plug-and-Play Stacks',
  'fcesc.feature.plug.desc': 'Pre-wired flytower stacks for rapid assembly. Professional FPV & cinematography ready out of the box.',
