  'fcesc.category.4in1': '4-in-1 ESC',
  'fcesc.category.separate': 'Separate ESC',

  // FC/ESC SEO Content
  'fcesc.seo.intro.title': 'Product Overview',
  'fcesc.seo.intro': 'CANI Technology professional FC/ESC system serves as the "core brain" and "power hub" of industrial drones. Featuring STM32 H7 autopilots with triple-redundant IMUs and high-voltage FOC ESCs (up to 24S/200A), our systems provide high-precision control and stable power output for multi-rotor and fixed-wing UAVs across power inspection, firefighting, surveying, and BVLOS missions.',
  'fcesc.techDetail.title': 'Technical Details',
  'fcesc.techDetail': 'Our FC systems use STM32H743/H753 MCUs (480MHz) for real-time Kalman filtering and high-frequency PID loops. Triple-redundant IMUs (ICM-42688-P + BMI270) on independent buses enable instant failover. ESCs feature Smart FOC vector control with 80A-200A continuous current, DroneCAN/UART telemetry, and over-temp/over-current/motor-lock protection.',
  'fcesc.caseStudy.title': 'Application Case Study',
  'fcesc.caseStudy': 'A drone manufacturer adopted our FC/ESC system for industrial inspection drone production. Testing showed autonomous route planning, fixed-point hovering, and auto-return functions. Flight stability improved by 60% with failure rate reduced to below 0.5%, significantly boosting product competitiveness and leading to a long-term strategic partnership.',

  // FC/ESC Category H2 Semantic Headings
  'fcesc.h2.autopilots': 'H7 Series Autopilots: The Brain of Industrial UAVs',
  'fcesc.h2.esc': 'High-Voltage FOC ESCs: Precise Power for Heavy-Lift Drones',
  'fcesc.h2.stacks': 'Plug-and-Play Stacks for Professional FPV & Cinematography',

  // FC/ESC Category FAQ
  'fcesc.faq.title': 'FC & ESC Technical FAQ',
  'fcesc.faq.subtitle': 'Expert answers to common flight controller and ESC questions for industrial UAV system integrators.',
  'fcesc.faq.q1': 'Why choose an H7 flight controller for industrial UAVs?',
  'fcesc.faq.a1': 'The H7 processor (running at 480MHz) provides the essential computational headroom for complex Kalman filtering, real-time obstacle avoidance, and high-frequency PID loops — ensuring superior flight stability in demanding environments where F4/F7 processors reach their limits.',
  'fcesc.faq.q2': 'How does triple-redundant IMU improve UAV safety?',
  'fcesc.faq.a2': 'By integrating three independent inertial sensors on separate buses, the FC can instantly detect data anomalies and switch to a healthy sensor within milliseconds, preventing catastrophic failures caused by vibration or sensor drift during critical missions.',
  'fcesc.faq.q3': 'What are the advantages of FOC ESCs over standard ESCs for heavy-lift drones?',
  'fcesc.faq.a3': 'FOC (Field-Oriented Control) ESCs provide higher efficiency, lower noise, smoother motor control, and real-time telemetry (temperature, RPM, current) via DroneCAN/UART. This translates to up to 10% longer flight time and industrial-grade operational reliability.',
  'fcesc.faq.q4': 'Are CANI FC/ESC systems NDAA compliant?',
  'fcesc.faq.a4': 'Yes. CANI offers NDAA-compliant hardware configurations designed for government and enterprise procurement requirements. Contact our team for BlueUAS-aligned product specifications.',
  'fcesc.faq.q5': 'Can I get a custom FC/ESC for my specific UAV platform?',
  'fcesc.faq.a5': 'Absolutely. CANI provides full OEM/ODM customization including firmware tuning, connector pinout, voltage range, current rating, and mounting form factor. Typical lead time is 15-30 business days.',

  // FC/ESC Detail Page
