  'gimbal.k40t.name': 'K40T 40x Optical Zoom Precision Gimbal Camera',
  'gimbal.k40t.slogan': 'The Eyes of the Sky for Long-Range Tactical Intelligence',
  'gimbal.k40t.subSlogan': 'K40T 40x Optical Zoom Precision Gimbal Camera',
  'gimbal.k40t.feature.quadLight': 'Quad-Sensor Fusion',
  'gimbal.k40t.feature.ultraClear': '40x Optical Zoom',
  'gimbal.k40t.feature.longDistance': '1200m Laser Ranging',
  'gimbal.k40t.feature.aiRecognition': 'AI Object Tracking',
  'gimbal.k40t.feature.weight': 'Gimbal Weight',
  'gimbal.k40t.highlight.1': '40x optical zoom + thermal imaging + wide-angle + laser rangefinder',
  'gimbal.k40t.highlight.2': 'AI-powered auto-tracking of vehicles and personnel',
  'gimbal.k40t.highlight.3': '1200m laser rangefinding with coordinate feedback',
  'gimbal.k40t.highlight.4': 'See clearly from 2km away — optical zoom vs. digital zoom advantage',
  'gimbal.k40t.desc.1': 'The K40T is an elite-grade 40x optical zoom gimbal camera engineered for missions where distance is a requirement, not an option. Whether conducting high-voltage powerline inspections or tactical border surveillance, the K40T allows operators to capture high-definition details from safe stand-off distances.',
  'gimbal.k40t.desc.2': 'Integrated with a high-precision 3-axis stabilization system, the K40T eliminates vibration even at maximum 40x zoom levels, providing a rock-steady video feed in Level 7 wind conditions.',
  'gimbal.k40t.desc.3': 'With advanced AI-powered object tracking, the gimbal automatically locks onto and follows moving targets (vehicles or personnel), making it the definitive payload for search and rescue and law enforcement.',
  'gimbal.k40t.desc.4': 'Quad-sensor fusion: 48MP visible zoom + 640×512 thermal + wide-angle + 1200m laser, all in a 290g precision-stabilized platform.',
  'gimbal.k40t.desc.5': 'Supports MAVLink/S.Bus control, HDMI/Ethernet video output, and plug-and-play integration with Pixhawk-based flight controllers.',
  'gimbal.k40t.featureItem.1': '40x optical zoom with lossless detail at 2km+',
  'gimbal.k40t.featureItem.2': '±0.005° 3-axis brushless stabilization',
  'gimbal.k40t.featureItem.3': 'AI auto-tracking: human/vehicle identification and coordinate feedback',
  'gimbal.k40t.featureItem.4': '1200m laser rangefinding for precision clearance analysis',
  'gimbal.k40t.featureItem.5': 'All-weather operation: IP65, -20°C to +55°C',
  'gimbal.k40t.app.1': 'Long-Range Powerline Inspection — Identify insulator cracks and wire strand breaks from 200m+ safe distance',
  'gimbal.k40t.app.2': 'Tactical Border Surveillance — Covert stand-off reconnaissance with AI target identification',
  'gimbal.k40t.app.3': 'Forest Fire Monitoring — Thermal hotspot detection through smoke and canopy at extreme range',
  'gimbal.k40t.app.4': 'Search & Rescue — Locate missing persons with AI-assisted scanning across wide areas',
  'gimbal.k40t.app.5': 'Infrastructure Inspection — Bridge, dam, and tower crack detection at safe stand-off distances',
  'gimbal.k40t.whitepaper.title': '📚 Tech Whitepaper: 40x Optical Zoom & AI Tracking Architecture',
  'gimbal.k40t.whitepaper.desc': 'How does the K40T achieve 40x lossless zoom, quad-sensor fusion, and 6TOPS AI edge computing in just 290g? Explore the multi-dimensional perception architecture for long-range reconnaissance.',
  'gimbal.k40t.whitepaper.cta': 'Read the Deep Technical Analysis',
  // K40T cross-link VTX
  'gimbal.k40t.crossVtx.title': 'Maximize Range: Pair with Zero-Latency VTX',
  'gimbal.k40t.crossVtx.desc': 'Pair the K40T 40x zoom with our FV10W/FV25W Ultra-High Power VTX for real-time 40x zoom feedback over 50km+. When you can see clearly from 2km, you need a link that delivers every frame instantly.',
  'gimbal.k40t.crossVtx.btn': 'Explore VTX Systems',
