  'gimbal.k8tv2.desc.1': 'The K8T-V2 is the next-generation evolution of our compact zoom series, balancing high-performance optics with an ultra-lightweight 162g form factor designed for agile UAV platforms',
  'gimbal.k8tv2.desc.2': 'V2 stabilization algorithm compensates for high-speed maneuvers and wind turbulence, ensuring crystal-clear imagery at full zoom — 30% faster auto-focus response vs. previous generation',
  'gimbal.k8tv2.desc.3': 'Dual-sensor fusion: 800MP visible light + 640×512 uncooled IR thermal imaging for 24/7 all-weather operation, with ≤50mK NETD sensitivity for subtle thermal anomaly detection',
  'gimbal.k8tv2.desc.4': '40x digital zoom combined with high-speed auto-focus captures critical details in seconds — ideal for rapid close-up industrial inspections',
