  'camera.sj4000.feature.1.title': '1080P Full HD Flight Imaging',
  'camera.sj4000.feature.1.desc': 'Captures crisp 1080P video at 1920×1080 resolution with WDR (Wide Dynamic Range) for clear detail in changing light — ideal for incident investigation and on-site inspection documentation.',
  'camera.sj4000.feature.2.title': '170° Wide-Angle Aerial Coverage',
  'camera.sj4000.feature.2.desc': 'Ultra-wide 170° field of view covers a broader operational area in a single pass, eliminating blind spots during infrastructure surveys and perimeter monitoring.',
  'camera.sj4000.feature.3.title': 'WiFi Real-Time Preview & Calibration',
  'camera.sj4000.feature.3.desc': 'Built-in WiFi enables pilots to preview footage, adjust settings, and calibrate the lens angle directly from a mobile device before takeoff — ensuring optimal framing for every mission.',
  'camera.sj4000.feature.4.title': 'Rugged All-Weather Protection',
  'camera.sj4000.feature.4.desc': 'Professional housing rated to 30m depth provides robust protection against rain, dust, and high-vibration environments typical of industrial UAV operations.',
  'camera.sj4000.feature.5.title': 'Versatile UAV Mounting System',
  'camera.sj4000.feature.5.desc': 'Standard 1/4" tripod adapter and bundled mounts enable quick attachment to drone platforms, anti-vibration dampers, and custom payload brackets.',
  'camera.sj4000.feature.6.title': 'Loop Recording (Flight Black Box)',
  'camera.sj4000.feature.6.desc': 'Automatic loop recording overwrites oldest footage when storage is full — functioning as a continuous flight black box for mission logging and post-flight analysis.',
