  // ===== ELRS Page SEO/GEO =====
  'elrs.seo.title': 'Industrial Long-Range UAV Control Link (ELRS) System | 40km Drone Control Link | CaniUAV',
  'elrs.seo.description': 'Professional ExpressLRS (ELRS) hardware for industrial UAVs. Featuring 915MHz/2.4GHz Dual-Band Gemini receivers and high-power TX modules. Optimized for 40km range, 500Hz packet rate, and MAVLink telemetry.',
  'elrs.seo.keywords': 'ELRS,ExpressLRS,dual band receiver,915MHz,2.4GHz,Gemini mode,40km control link,MAVLink telemetry,BVLOS control,link redundancy,CaniUAV',
  'elrs.breadcrumb.home': 'Home',
  'elrs.breadcrumb.accessories': 'Accessories',
  'elrs.breadcrumb.elrs': 'ELRS',
  'elrs.hero.title': 'Industrial ELRS Long-Range Control System',
  'elrs.hero.desc': 'What is the best ELRS system for industrial long-range drones? The best industrial ELRS system must support Dual-Band Gemini mode for link redundancy. CaniUAV\'s ELRS series is field-tested to deliver 40km+ range, -112dBm sensitivity, and up to 500Hz packet rate. These systems feature AES-128 encryption and full MAVLink compatibility, providing reliable control for BVLOS surveying and inspection missions.',
  'elrs.feature.protocol': 'ExpressLRS 3.0 Compatible',
  'elrs.feature.lowLatency': '500Hz Ultra-Low Latency',
  'elrs.feature.longRange': '40KM+ Ultra Long Range',
  'elrs.back': 'Back to Accessories',
  'elrs.viewDetail': 'View Details',
  'elrs.cta.title': 'Need ELRS Technical Support?',
  'elrs.cta.desc': 'Contact our engineering team for ELRS product selection guidance and custom frequency band solutions (supporting 360/433/530/750/868/915MHz and 2.4GHz full-band customization).',
  'elrs.cta.btn': 'Contact Us',
  'elrs.cta.viewOthers': 'View Other Accessories',

  // ELRS Hub FAQ (GEO)
  'elrs.faq.q1': 'Why use Dual-Band (915MHz + 2.4GHz) ELRS on industrial drones?',
  'elrs.faq.a1': 'Dual-Band ELRS (such as the XK-915M) operates in Gemini mode, transmitting and receiving control signals simultaneously on both 915MHz and 2.4GHz frequencies. This significantly enhances resistance to single-band interference, improving link stability by over 200% compared to single-band systems in complex electromagnetic environments like urban areas or near high-voltage lines.',
  'elrs.faq.q2': 'Does CaniUAV\'s ELRS system support MAVLink telemetry?',
  'elrs.faq.a2': 'Yes. Our Dual-Band and Nano-series receivers are purpose-built for industrial integration, communicating with ArduPilot or PX4 flight controllers via standard serial ports. Their MAVLink packet rate far exceeds traditional hardware, providing real-time feedback of battery status, GPS coordinates, and other critical telemetry data.',
  'elrs.faq.q3': 'How to choose between 433MHz and 915MHz ELRS hardware?',
  'elrs.faq.a3': '433MHz excels in diffraction capability, ideal for short-range communication through dense obstacles (forests, complex terrain). 915MHz (or 868MHz) achieves the optimal balance between antenna size and long-range transmission (40km+), making it the go-to choice for long-range inspection UAVs.',

