  'softwarePage.pvInspection.faq.title': 'PV Inspection Expert Q&A',
  'softwarePage.pvInspection.faq.q1': 'How does the CANI PV inspection software ensure IEC 62446-3 compliance?',
  'softwarePage.pvInspection.faq.a1': 'The system auto-validates IEC 62446-3 environmental conditions (irradiance ≥600W/m², cloud cover ≤2 oktas) and locks flight altitude for GSD ≤3cm/pixel in mission planning. Gimbal auto-compensation ensures camera angle perpendicular to panels (±20° tolerance), and emissivity correction algorithms guarantee measurement reliability. It then auto-generates standardized compliance reports.',
  'softwarePage.pvInspection.faq.q2': 'What drone platforms and thermal sensors are supported?',
  'softwarePage.pvInspection.faq.a2': 'The software is compatible with DJI Mavic 3T (640×512 thermal), DJI M30T, FLIR Vue Pro, and other mainstream platforms via standardized PSDK/MSDK interfaces. It also integrates seamlessly with CANI self-developed drone airports for fully autonomous unattended inspection.',
  'softwarePage.pvInspection.faq.q3': 'How does the system scale for 100MW+ large solar farms?',
  'softwarePage.pvInspection.faq.a3': 'The CANI PV inspection system uses distributed cloud architecture, completing full-coverage inspection of a 100MW farm in one day (vs 30 days manual). It supports multi-drone coordinated operations, automatic flight path allocation, and provides 3D digital twin models for historical data overlay and predictive maintenance.',
  'softwarePage.pvInspection.faq.q4': 'How does it reduce solar farm OPEX?',
  'softwarePage.pvInspection.faq.a4': 'Through the "drone airport + AI inspection software" closed loop, it eliminates manual inspection travel and labor costs. The system auto-schedules inspections, AI analyzes defects in real-time, generates repair work orders, and combined with predictive maintenance reduces unplanned downtime. Case studies show OPEX reduction of over 40%, and a 100MW farm can avoid 5.77% generation loss from faults (approximately 249 IRR basis points).',

  'softwarePage.pvInspection.cta.title': 'Enter the Era of Intelligent Solar Asset O&M',
  'softwarePage.pvInspection.cta.subtitle': 'Get the CANI PV Inspection System technical whitepaper and custom demo. Learn how AI + drone airports can reduce OPEX by 40%.',
