  'softwarePage.management.faq.title': 'Drone Management Expert Q&A',
  'softwarePage.management.faq.q1': 'How does the CANI platform achieve automatic DJI flight log sync?',
  'softwarePage.management.faq.a1': 'The platform uses DJI Cloud API and MSDK interfaces to automatically capture takeoff/landing times, GPS trajectories, telemetry parameters, and anomaly event logs from every flight. Data is encrypted upon upload with tamper-proof audit trails, meeting FAA Part 107 and EASA record-keeping requirements. PX4 and ArduPilot flight controller logs are also supported.',
  'softwarePage.management.faq.q2': 'Which compliance frameworks does the system support?',
  'softwarePage.management.faq.a2': 'The platform includes built-in FAA Part 107/108, EASA A1-A3/A2, China CAAC, and SORA operational risk assessment frameworks. It auto-generates jurisdiction-specific compliance reports, reducing audit prep from 8 hours to 30 minutes.',
  'softwarePage.management.faq.q3': 'How does the system manage battery health for large fleets?',
  'softwarePage.management.faq.a3': 'Each battery gets a digital profile tracking charge/discharge cycles, internal resistance trends, and SOH scores. When batteries reach preset thresholds (e.g., 300 cycles or SOH drops to 80%), the system auto-triggers replacement alerts and purchase recommendations, preventing 95%+ of battery-related in-flight failures.',
  'softwarePage.management.faq.q4': 'How does the platform scale for different enterprise sizes?',
  'softwarePage.management.faq.a4': 'The CANI Management Platform uses microservices architecture, scaling elastically from 10-aircraft small fleets to 500+ enterprise operations. It supports both private deployment and SaaS cloud modes, with REST API and Webhook interfaces for seamless integration with existing ERP/MES systems.',

  'softwarePage.management.cta.title': 'Build Your Digital Drone Operations System',
  'softwarePage.management.cta.subtitle': 'Get a CANI Drone Management Platform enterprise demo and learn how to reduce operations admin hours by 40%.',

