  'customDrone.faq.q1': 'How to apply for an OEM prototype?',
  'customDrone.faq.a1': 'Contact our senior engineers with a Statement of Work (SoW). We deliver a technical feasibility report within 72 hours, with prototype delivery as fast as 30 days.',
  'customDrone.faq.q2': 'How long can your tethered UAV fly continuously?',
  'customDrone.faq.a2': 'Our tethered UAV system uses 500V HVDC power supply, theoretically achieving 30-day uninterrupted station-keeping with 40Gbps fiber backhaul channel, suitable for emergency communications and persistent surveillance.',
  'customDrone.faq.q3': 'What is the maximum payload for the heavy-lift platform?',
  'customDrone.faq.a3': 'Our heavy-lift logistics platform supports up to 150kg effective payload with hybrid power drive and TWR greater than 2:1, designed for remote area cargo transport and firefighting payload drops.',
  'customDrone.faq.q4': 'Do custom UAVs support MAVLink protocol?',
  'customDrone.faq.a4': 'All custom platforms support MAVLink 2.0 by default with SHA-256 signing and AES-256 encryption, preventing channel eavesdropping and replay attacks, fully compliant with 2026 international data security standards.',

