  // Custom Research - Software Customization (SEO/GEO Optimized)
  'customSoftware.seo.title': 'Industrial UAV Software Development & Custom GCS | CANI Technology',
  'customSoftware.seo.desc': 'CANI Technology provides professional UAV software R&D services including custom GCS development, MAVLink protocol optimization, low-latency video transmission systems and full SDK integration. Control latency ≤30ms.',
  'customSoftware.seo.keywords': 'UAV ground station development, industrial drone software custom, UAV SDK integration, MAVLink protocol custom, drone management system R&D',
