  'swarm.w400intelligentsystemsection.k350': 'Autonomously adjusts coordinate origins based on RTK positioning data to unify the coordinate system. Each drone starts with its GPS position as the (0,0) origin, then RTK differential data corrects in real-time, mapping all UAVs into a unified global coordinate frame for precise swarm formation positioning.',
