  'acc.fcescdetail.k564': 'Explore 60A high-current thermal management, bidirectional DShot RPM filtering, and X8 heavy-lift architecture',
  'acc.fcescdetail.k565': 'Small Size, Big Computing Power: How Stack-Mini F7-40A Defines Control Limits of Compact UAVs',
  'acc.fcescdetail.k566': 'Explore F722 low-latency PID control, 40A high-density current design, and bidirectional DShot RPM filtering',
  'acc.fcescdetail.k567': 'Peak Power: How Stack-Pro F722-100A Solves Current Anxiety for Heavy-Lift UAVs',
  'acc.fcescdetail.k568': 'Explore 100A power engineering, 8-layer PCB thermal design, and dual ICM42688 redundant gyroscope architecture',
  'acc.fcescdetail.k569': 'Simplifying Power Revolution: How CANI-80A 6-in-1 ESC Reshapes Hexacopter Structural Design',
  'acc.fcescdetail.k570': 'Explore 6-channel integrated ESC structural advantages, CNC thermal engineering, and MAVLink real-time telemetry',
  'acc.fcescdetail.k571': 'Engineering Philosophy of Stability: CANI-FC F405 Anti-Interference Capability Analysis',
  'acc.fcescdetail.k572': 'Explore F405 industrial EMI-resistant layout, MPU6000 physical IMU protection, and multi-UART sensor matrix expansion',
  'acc.fcescdetail.k573': 'Six-Channel 100A Integration: How CANI-100A 6-in-1 ESC Breaks Through Power Density Limits',
  'acc.fcescdetail.k574': 'Explore 100A power density, 7-series aviation aluminum CNC thermal engineering, and bidirectional DShot real-time telemetry',
  'acc.fcescdetail.k575': 'Computing Power Reshapes Flight: How CANI-FC F722 Determines UAV Attitude Stability in Milliseconds',
  'acc.fcescdetail.k576': 'Explore 216MHz F7 computing advantages, ultra-fast PID loops, and 10V independent BEC digital VTX integration',
  'acc.fcescdetail.k577': 'Foundation of Heavy-Lift Flight: Deep Analysis of CANI-ESC 60A Electrical Robustness Under High-Load Missions',
  'acc.fcescdetail.k578': 'Explore CNC aviation aluminum heat armor, low RDS(on) MOSFET technology, conformal coating, and full digital telemetry loop',
  'acc.fcescdetail.k579': 'Ultimate Heavy-Lift Power Challenge: How CANI-ESC 80A Achieves Zero Thermal Drift Under 8S High-Voltage',
  'acc.fcescdetail.k580': 'Explore dual MOSFET parallel topology, dual-layer CNC heat armor, dual TVS protection, and 8S high-voltage efficiency',
  'acc.fcescdetail.k581': 'The Art of Current Management: How CANI-ESC 55A Maintains Power Linearity Under Extreme Load',
  'acc.fcescdetail.k582': 'Explore CNC heat armor, 8-layer PCB thermal design, TDK capacitor array, and bidirectional DShot telemetry loop',
  'acc.fcescdetail.k583': 'Breaking the 100A Barrier: How CANI-ESC 100A Achieves Ultimate Reliability in High-Power UAV Systems',
  'acc.fcescdetail.k584': 'Explore 10-layer 4oz ENIG PCB, 360° CNC thermal armor, industrial TVS arrays, and full-chain telemetry monitoring',
  'acc.fcescdetail.k585': 'Physical Isolation of High-Voltage Power: CANI 100A Separate ESC Performance in 12S Systems',
