  'vtxDetail.fv10w72.seo.title': 'FV10W-72 | 10W 720MHz Analog VTX | Ultra-Deep NLOS Penetration | CANI UAV',
  'vtxDetail.fv10w72.seo.desc': 'The FV10W-72 is a 10W high-power analog VTX operating on the 720MHz (UHF) band. Engineered for extreme diffraction and penetration in dense forests, mountains, and underground environments.',
  'vtxDetail.fv10w72.h1': 'FV10W-72: 10,000mW (10W) 700MHz-Band Extreme NLOS Link',
  'vtxDetail.fv10w72.overview': 'When traditional 2.4GHz and 5.8GHz systems fail due to dense foliage or mountainous terrain, the FV10W-72 takes over. Operating in the 720MHz (UHF) band with a massive 10,000mW (10W) output, this transmitter utilizes the physical advantages of lower frequencies to provide unparalleled signal diffraction. Unlike higher frequencies that require a clear line-of-sight, the 720MHz carrier bends around geographical obstacles and penetrates deep into forest canopies and industrial structures. Encased in a heavy-duty CNC heat sink with active cooling, the FV10W-72 is the definitive choice for Search and Rescue (SAR), remote forestry monitoring, and specialized tactical missions where maintaining a zero-latency video link through the unreachable is mandatory.',
  'vtxDetail.fv10w72.wp.title': 'Technical White Paper: Why 700MHz (UHF) is the Definitive Choice for Complex SAR',
  'vtxDetail.fv10w72.wp.intro': 'In Search and Rescue (SAR) missions, the environment is the enemy. While 5.8GHz systems are standard for open-field operations, they fail catastrophically when Line-of-Sight is broken by heavy foliage, rock formations, or mountain ridges. The FV10W-72 was engineered to solve the Visual Cut-off problem using the fundamental physics of radio wave propagation.',
  'vtxDetail.fv10w72.wp.s1.title': 'The Physics of Diffraction: Bending Around Mountains',
  'vtxDetail.fv10w72.wp.s1.text': 'At the Sub-1GHz band, the wavelength is significantly longer (~41cm). This allows the signal to perform Diffraction — literally bending around mountain peaks, ridges, and dense tree canopies. Even when the drone drops behind a ridge or into a valley, the 720MHz signal utilizes terrain edges to reach the ground station, maintaining a vital visual link where 5.8GHz would go black.',
  'vtxDetail.fv10w72.wp.s2.title': 'Superior Vegetation Penetration (Forestry Missions)',
  'vtxDetail.fv10w72.wp.s2.text': 'Moisture in leaves and the density of wood are highly effective at absorbing 2.4GHz and 5.8GHz signals. 720MHz waves pass through organic matter with much lower attenuation. In a dense forest environment, a 10W 720MHz link can achieve 5-10x the effective range of a 10W 5.8GHz link. SAR teams can track missing persons or fire fronts deep within forest canopies without losing real-time feedback.',
  'vtxDetail.fv10w72.wp.s3.title': 'Overcoming Multi-path Interference in Canyons',
  'vtxDetail.fv10w72.wp.s3.text': 'In narrow valleys or urban canyons, signal reflections create ghosting or digital pixelation. By using a high-power analog carrier at 720MHz, the FV10W-72 provides graceful degradation — instead of a sudden digital freeze, the operator gets a slightly snowy but continuous image, allowing for reactive piloting to regain a stronger signal.',
  'vtxDetail.fv10w72.wp.s4.title': 'Strategic Implementation: The 10W Power Budget',
  'vtxDetail.fv10w72.wp.s4.text': 'At 10,000mW, the FV10W-72 provides enough Link Budget to compensate for free-space path loss of the UHF band. Pair with a UHF Yagi or Dipole antenna on the ground station to maximize the 700MHz gain. The integrated CNC active cooling ensures the 10W output remains stable during extended 2-hour+ search patterns.',
  'vtxDetail.fv10w72.antennaWarning': 'Requires frequency-matched UHF antennas. The 720MHz antenna aperture is significantly larger than 5.8GHz — ensure proper impedance matching (50-ohm) for maximum efficiency.',
  'vtxDetail.fv10w72.freqCustom': 'Customized frequency tuning (600MHz - 900MHz) available upon request — demonstrating CANI UAV\\\'s deep R&D capability as an original equipment manufacturer.',
  'vtxDetail.fv10w72.isolationNote': 'Note: This UHF analog system is a specialized independent accessory designed for extreme NLOS environments. It is not integrated into our autonomous swarm or logistics platforms, which utilize dedicated digital mesh networks.',
  'vtxDetail.fv10w72.faq.q1': 'Why choose a 720MHz VTX over 5.8GHz for search and rescue missions?',
  'vtxDetail.fv10w72.faq.a1': 'The 720MHz (UHF) band provides fundamentally superior diffraction and vegetation penetration compared to 5.8GHz. The longer wavelength (~41cm vs ~5cm) allows the signal to physically bend around mountains, ridges, and dense tree canopies. In dense forest environments, a 10W 720MHz link achieves 5-10x the effective range of an equivalent 5.8GHz system, making it indispensable for SAR, forestry monitoring, and underground operations.',
  'vtxDetail.fv10w72.faq.q2': 'What antenna is required for the FV10W-72 720MHz VTX?',
  'vtxDetail.fv10w72.faq.a2': 'Due to the lower operating frequency, the FV10W-72 requires frequency-matched UHF antennas with significantly larger aperture than standard 5.8GHz antennas. We recommend a high-gain UHF Yagi or Dipole antenna on the ground station side, and a quarter-wave whip or folded dipole on the airborne side. All antennas must be 50-ohm impedance matched to ensure maximum power transfer.',
  'vtxDetail.fv10w72.faq.q3': 'Can the FV10W-72 frequency be customized for different regional regulations?',
  'vtxDetail.fv10w72.faq.a3': 'Yes. As an original equipment manufacturer, CANI UAV offers frequency customization across the 600MHz-900MHz range to comply with regional radio regulations. This includes custom crystal oscillator tuning and band-pass filter optimization for specific authorized frequency allocations.',
  'acc.vtxvrx.k651': '📡 Receiver Modules (VRX)',
  'acc.vtxvrx.k652': 'Industrial-grade analog video receiver cores with -97dBm flagship sensitivity, zero-latency reception, and plug-and-play integration.',
  'acc.vtxvrx.k653': 'View Details',
  'acc.meshlink.k654': 'Mesh-Link: Industrial Breakthrough in UAV Ad-hoc Networking & Mesh Relay',
  'acc.meshlink.k655': 'Complete technical analysis from decentralized networking to dynamic topology recovery, including path optimization and WiFiLink2 integration',
