  // WiFiLink2 SEO & Sections
  'digitalFpv.wifilink2.seo.title': 'WiFiLink2 | 1080P HD Digital Video Link | Low Latency & High Efficiency | CANI UAV',
  'digitalFpv.wifilink2.seo.description': 'The WiFiLink2 is a high-performance 1080P digital video transmission system built on the OpenIPC open-source platform. Featuring H.265 encoding and 5GHz WiFi broadband, it delivers cost-effective HD clarity for industrial inspections and tactical UAVs.',
  'digitalFpv.wifilink2.arch.title': 'Open Architecture: The Best Starting Point for Custom Development',
  'digitalFpv.wifilink2.arch.desc': 'WiFiLink2 is built on the OpenIPC open-source ecosystem, providing full Linux-level access and API interfaces. System integrators can customize OSD overlays, telemetry data injection, and video stream routing without reverse engineering.',
  'digitalFpv.wifilink2.arch.open': 'OpenIPC Open-Source Firmware',
  'digitalFpv.wifilink2.arch.openDesc': 'Linux-based open firmware ecosystem with a global developer community for continuous updates and unlimited feature expansion',
  'digitalFpv.wifilink2.arch.api': 'API & Custom OSD',
  'digitalFpv.wifilink2.arch.apiDesc': 'Supports custom OSD overlay layers, MAVLink telemetry data injection, and UDP/TCP video stream routing configuration',
  'digitalFpv.wifilink2.arch.ruby': 'Ruby FPV Dual System',
  'digitalFpv.wifilink2.arch.rubyDesc': 'One-click switching between OpenIPC and Ruby FPV firmware to adapt to different mission requirements and development preferences',
  'digitalFpv.wifilink2.arch.mobile': 'Instant Mobile Preview',
  'digitalFpv.wifilink2.arch.mobileDesc': 'WiFi direct connection to smartphones or tablets without additional ground station hardware. Complete deployment in under 5 minutes',
  'digitalFpv.wifilink2.crossLink.title': 'Best-Value Digital HD Solution',
  'digitalFpv.wifilink2.crossLink.desc': 'WiFiLink2 is the ideal bridge between analog VTX and professional data links. At a fraction of the S900 Datalink cost, it delivers crystal-clear 1080P imagery for budget-conscious integrators who demand visual clarity.',
  'digitalFpv.wifilink2.crossLink.monitors': 'View Compatible Ground Station Monitors',
  'digitalFpv.wifilink2.crossLink.analog': 'Need Extreme Penetration? View Analog VTX Series',
  'digitalFpv.wifilink2.crossLink.s900': 'Need Triple-Play Datalink? View S900',
  // Mesh Link Page Keys
  'meshLink.seo.title': 'CANI Mesh-Link | Self-Healing MANET Tactical Mesh Radio | Swarm Communication | CANI UAV',
  'meshLink.seo.description': 'CANI Mesh-Link is an industrial-grade self-healing MANET mesh module. Supporting 800M/1.4G/2.4G tri-band, 7+ hop relay and 15ms topology recovery for UAV swarms, mine rescue, and complex NLOS environments.',
  'meshLink.seo.keywords': 'UAV Mesh Network,MANET,self-healing mesh,multi-hop relay,NLOS,swarm communication,COFDM,FHSS,tactical datalink,ad-hoc network',
  'meshLink.back': 'Back to Accessories',
  'meshLink.breadcrumb.home': 'Home',
  'meshLink.breadcrumb.accessories': 'Accessories',
  'meshLink.breadcrumb.current': 'Tactical Mesh Link Module',
  'meshLink.hero.title': 'Mesh-Link: Tactical Self-Healing MANET Radio',
  'meshLink.hero.subtitle': 'The Ultimate Communication Backbone for Swarms & Complex Environments',
  'meshLink.hero.desc': 'Built on MANET (Mobile Ad-hoc Network) technology, each node automatically calculates optimal data paths. When a node is blocked or lost, the network rebuilds topology within 15ms ensuring zero mission interruption. Supports 7+ hop relay, 800MHz penetration through 4 concrete floors, and 17km omnidirectional air-to-ground coverage.',
  'meshLink.highlight.distance': '17km Omni Coverage',
  'meshLink.highlight.penetration': '4-Floor Penetration',
  'meshLink.highlight.diffraction': 'Multi-Hop Relay',
  'meshLink.highlight.lowPower': 'Power ≤3.5W',
  'meshLink.highlight.antiInterference': 'FHSS Anti-Jamming',
  'meshLink.features.title': 'Core Technical Advantages',
  'meshLink.feature.range.title': '17km Ultra Long-Range Omni Transmission',
  'meshLink.feature.range.desc': '17km air-to-ground 360° omnidirectional transmission, field-tested with stable 1080P imagery for BVLOS missions',
  'meshLink.feature.penetration.title': 'Deep NLOS Penetration',
  'meshLink.feature.penetration.desc': '800MHz low-frequency penetrates 4 concrete floors. Vortex-mode transmission for non-line-of-sight coverage in rain, snow, and fog',
  'meshLink.feature.mesh.title': 'Self-Healing Mesh Networking',
  'meshLink.feature.mesh.desc': 'Supports 1V1, 1V16 star topology and advanced Mesh multi-point communication. 15ms automatic topology recovery on node failure for zero-interruption coverage',
  'meshLink.feature.frequency.title': 'Tri-Band Tactical Selection',
  'meshLink.feature.frequency.desc': '800M (deep penetration) / 1.4G (balanced performance) / 2.4G (high throughput) — customizable for different tactical spectrum requirements',
  'meshLink.feature.power.title': 'Ultra-Low Power for Extended Endurance',
  'meshLink.feature.power.desc': 'Peak power consumption only 3.5W with DC 7-24V wide voltage input, maximizing UAV flight endurance',
  'meshLink.feature.latency.title': '15ms Ultra-Low Latency Link',
  'meshLink.feature.latency.desc': 'Air interface latency only 15ms, boot-to-link in under 15 seconds for millisecond-level swarm coordination',
  'meshLink.advantages.title': 'Five Core Capabilities',
