  'logisticsApp.scenario.emergency.detail': '在地震、洪水、泥石流等自然灾害发生后，道路往往被毁坏，传统运输方式难以进入灾区。无人机可以快速将急救药品、医疗器械、食品、饮用水等紧急物资送达灾区，为抢救生命争取宝贵时间。',
