  'logisticsApp.scenario.island.detail': '我国拥有众多海岛，其中有人居住的海岛超过450个。海岛居民的物资供应长期依赖船舶运输，受天气、潮汐等因素影响较大。无人机物流配送可以跨越海洋，在恶劣天气无法通航时仍能保障物资供应。',
