  'logisticsApp.scenario.remote.detail': '我国山区面积占国土总面积的三分之二以上，许多偏远山区交通不便，传统物流配送成本高、时效差。无人机物流配送突破地形限制，可以直线飞行到达目的地，将原本需要数天的配送时间缩短到数小时。',
