  'logisticsApp.scenario.urban.detail': '随着电商和即时配送的快速发展，城市末端配送需求激增。传统的人工配送面临人力成本高、交通拥堵、配送时效不稳定等问题。无人机末端配送可以避开地面交通，实现点对点快速配送。',
